370	func TestDependencyWaitDoesNotBlockRunnableJobs(t *testing.T) {
371		s, _ := openTestStore(t)
372		started, block, release, _, _ := gateCompute(t, s)
373		block(1)
374	
375		first := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}}) // id 1 占住位置
376		waitStarted(t, started, first.ID)
377	
378		waiting := mustSubmit(t, s, SubmitRequest{ // id 2 等 id 1 的结果
379			Submitter: "a", Values: []int64{2},
380			HasDependency: true, DependencyID: first.ID,
381		})
382		runnable := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{3}}) // id 3 无依赖
383	
384		// 唯一位置正被 id 1 占用：id 2 说明在等依赖结果，id 3 说明在等计算位置。
385		if j, _ := s.Get(waiting.ID); j.WaitReason != WaitDependency {
386			t.Fatalf("waiting job reason=%q, want WaitDependency", j.WaitReason)
387		}
388		if j, _ := s.Get(runnable.ID); j.WaitReason != WaitSlot || j.Status != StatusQueued {
389			t.Fatalf("runnable job status=%s reason=%q, want queued/WaitSlot", j.Status, j.WaitReason)
390		}
391	
392		// 上游取消：id 2 必须失败并指出阻断者，而 id 3 必须照常被排空，
393		// 证明等待依赖的作业没有把队列堵死。
394		if _, err := s.Cancel(first.ID); err != nil {
395			t.Fatalf("cancel: %v", err)
396		}
397		release(first.ID)
398		failed := waitStatus(t, s, waiting.ID, StatusFailed)
399		if failed.BlockerID != first.ID {
400			t.Fatalf("blocker=%d want %d", failed.BlockerID, first.ID)
401		}
402		done := waitStatus(t, s, runnable.ID, StatusSucceeded)
403		if done.Archive.Sum != 3 {
404			t.Fatalf("independent job result=%d, want 3", done.Archive.Sum)
405		}
406	}
