func TestDependencyAppendsDependencySum(t *testing.T) {
	s, _ := openTestStore(t)
	base := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}, Seed: 0})
	waitStatus(t, s, base.ID, StatusSucceeded) // sum=3
