package numeric

import (
	"bytes"
	"encoding/json"
	"unicode/utf8"
)

// rawText 是按“完整原始字节”保存和恢复的标识文本：提交人与请求号允许
// 包含任意 Go 字符串字节，包括 U+0000 与不能组成合法 UTF-8 的字节。
//
// 普通 [encoding/json] 把 string 当作 UTF-8 文本处理：非法字节在 Marshal
// 时被替换为 U+FFFD，Unmarshal 时也无法复原——含非法 UTF-8 的标识落盘后
// 会变成另一个字符串，原请求找不到自己的作业，不同标识还可能塌缩成同一
// 条记录。rawText 自己实现 JSON 字符串的转义与反转义，除 UTF-8 文本外
// 还会把每个无法解码为符文的字节转义为 uFFXX，从而逐字节往返；它不实现
// html 转义（记录经 MarshalIndent 写入，SetEscapeHTML 不影响自描述编码）。
type rawText string

// rawMarshal 以调用方给出的完整字节构造落盘标识。
func rawMarshal(s string) rawText { return rawText(s) }

// String 按完整字节还原为 Go 字符串标识。
func (r rawText) String() string { return string(r) }

// MarshalJSON 把原始字节编码为 JSON 字符串。合法 UTF-8 符文按 UTF-8 原样
// 输出（其中需要转义的引号、反斜杠与控制字符按 JSON 规则转义）；不能组成
// 合法 UTF-8 的单个字节输出为 uFFXX，XX 为该字节的十六进制值，
// 例如 0xFF → 。
func (r rawText) MarshalJSON() ([]byte, error) {
	var b bytes.Buffer
	b.WriteByte('"')
	s := []byte(r)
	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
			i++
		case c == '\\':
			b.WriteString(`\\`)
			i++
		case c == '\n':
			b.WriteString(`\n`)
			i++
		case c == '\r':
			b.WriteString(`\r`)
			i++
		case c == '\t':
			b.WriteString(`\t`)
			i++
		case c < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte(hexDigit(c >> 4))
			b.WriteByte(hexDigit(c))
			i++
