	}
	defer s.Close()
	g, err := s.Get(1)
	if err != nil {
		t.Fatal(err)
	}
	if g.Submitter != "alice" || g.RequestID != "r\x001" {
		t.Fatalf("旧记录标识错误：%q,%q", g.Submitter, g.RequestID)
