	// 旧幂等号继续生效。
	again, err := s.Submit(SubmitRequest{
		Submitter: "alice", RequestID: "r\x001", Values: []int64{1, 2},
	})
	if err != nil || again.ID != 1 {
		t.Fatalf("旧幂等号重放：id=%d err=%v，要 1", replayID(again), err)
	}
}

func idsOf(js []*Job) []uint64 {
	out := make([]uint64, len(js))
	for i, j := range js {
		out[i] = j.ID
	}
	return out
}

